from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import unquote,urlsplit
import json,re,unicodedata
root=Path('.')
class Page(HTMLParser):
 def __init__(self,text):
  super().__init__();self.section=None;self.h1=False;self.topic=False;self.word='';self.theme='';self.links=[];self.redirect=None;self.feed(text)
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if tag=='meta' and a.get('http-equiv','').lower()=='refresh':self.redirect=re.split('url=',a.get('content',''),flags=re.I)[-1].strip()
  if tag=='h1':self.h1=True
  if tag=='p' and a.get('class')=='tema':self.topic=True
  if tag=='section':self.section=a.get('id')
  if tag=='a' and self.section in ('sinonimos','analogas'):self.links.append(a.get('href',''))
 def handle_endtag(self,tag):
  if tag=='section':self.section=None
  if tag=='h1':self.h1=False
  if tag=='p':self.topic=False
 def handle_data(self,data):
  if self.h1:self.word+=data
  if self.topic:self.theme+=data
pages={p.name.casefold():Page(p.read_text(encoding='utf-8')) for p in Path('site').glob('*.html')}
def key(href):return unquote(urlsplit(href).path).split('/')[-1].casefold()
def resolve(href):
 k=key(href);seen=set()
 while k in pages and pages[k].redirect:
  if k in seen:return None
  seen.add(k);k=key(pages[k].redirect)
 return k if k in pages and pages[k].theme else None
valid={k:p for k,p in pages.items() if p.theme}
names={k:unicodedata.normalize('NFC',p.word.strip().lower()) for k,p in valid.items()}
graph={w:set() for w in names.values()};missing=[];raw=0
for k,p in valid.items():
 for href in p.links:
  raw+=1;t=resolve(href)
  if t is None:missing.append({'source':names[k],'target':href});continue
  a,b=names[k],names[t]
  if a!=b:graph[a].add(b);graph[b].add(a)
data={w:sorted(v) for w,v in sorted(graph.items())}
pairs=sum(map(len,data.values()))//2
rank=sorted(data,key=lambda w:(-len(data[w]),w))
result={'words':len(data),'relations':pairs,'most_connected':rank[0],'most_connected_ties':[w for w in rank if len(data[w])==len(data[rank[0]])],'max_degree':len(data[rank[0]])}
Path('words.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
Path('result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
themes={names[k]:p.theme.replace('Tema:','').strip() for k,p in valid.items()}
aliases={}
for k,p in pages.items():
 if p.redirect:
  t=resolve(k)
  if t:aliases[unquote(k[:-5])]=names[t]
payload={'words':data,'themes':themes,'aliases':aliases,'result':result}
Path('data-inline.json').write_text(json.dumps(payload,ensure_ascii=False),encoding='utf-8')
Path('extraction-report.json').write_text(json.dumps({'html_files':len(pages),'word_pages':len(valid),'redirects':len(aliases),'relation_links_before_deduplication':raw,'unresolved_links':missing,'top_words':[{'word':w,'degree':len(data[w])} for w in rank[:12]],'assumptions':['Only links inside sinonimos and analogas sections are relations.','Redirects resolve to canonical h1 labels, normalized to lowercase NFC; accents are preserved.','Relations are undirected; repeated pairs and self links are removed.','Missing targets and non-word pages are excluded.']},ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps(result,ensure_ascii=False));print('Themes:',sorted(set(themes.values())));print('Missing links:',len(missing));print('Top:',[(w,len(data[w])) for w in rank[:5]])


